DROP TABLE IF EXISTS `expense_form`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `expense_form` (
  `expense_id` int NOT NULL AUTO_INCREMENT,
  `emp_id` int NOT NULL,
  `project_id` int NOT NULL,
  `claim_amount` decimal(10,2) DEFAULT '0.00',
  `status` enum('draft','pending','coordinator_approved','coordinator_rejected','hr_approved','hr_rejected','accounts_approved','accounts_rejected') DEFAULT 'draft',
  `coordinator_comment` text,
  `hr_comment` text,
  `accounts_comment` text,
  `coordinator_reviewed_by` int DEFAULT NULL,
  `hr_reviewed_by` int DEFAULT NULL,
  `accounts_reviewed_by` int DEFAULT NULL,
  `coordinator_reviewed_at` timestamp NULL DEFAULT NULL,
  `hr_reviewed_at` timestamp NULL DEFAULT NULL,
  `accounts_reviewed_at` timestamp NULL DEFAULT NULL,
  `submitted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `site_location_override` varchar(255) DEFAULT NULL,
  `project_coordinator_hod_override` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`expense_id`),
  KEY `idx_expense_emp` (`emp_id`),
  KEY `idx_expense_proj` (`project_id`),
  KEY `idx_expense_status` (`status`),
  CONSTRAINT `expense_form_ibfk_1` FOREIGN KEY (`emp_id`) REFERENCES `employees` (`emp_id`) ON DELETE CASCADE,
  CONSTRAINT `expense_form_ibfk_2` FOREIGN KEY (`project_id`) REFERENCES `projects` (`project_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
